// Config from Set node, raw webhook from named node reference
const config      = $input.first().json;
const webhookData = $('Receive Message from Laravel').first().json;

// ─── Security: verify X-N8N-Secret header ─────────────────────────────
const receivedSecret = webhookData.headers?.['x-n8n-secret']
                    || webhookData.headers?.['X-N8N-Secret']
                    || '';
const expectedSecret = config.n8nSecret || 'change-me-in-production';

if (receivedSecret !== expectedSecret) {
  throw new Error('401: Invalid X-N8N-Secret header. Received: [' + receivedSecret + ']');
}

// ─── Extract body ──────────────────────────────────────────────────────
const body = webhookData.body || webhookData;

const messageId      = body.message_id;
const conversationId = body.conversation_id;
const content        = body.content;
const categoryId     = body.category_id  || null;
const history        = body.history       || [];
const mediaUrl       = body.media_url     || null;
const isImage        = body.is_image      === true;

if (!messageId || !conversationId || (!content && !isImage)) {
  throw new Error('400: Missing required fields');
}

const historyMessages = history.slice(-10).map(turn => ({
  role:    turn.role === 'user' ? 'user' : 'assistant',
  content: turn.content || '[audio]'
}));

return [{
  json: {
    messageId, conversationId, categoryId, content, historyMessages,
    mediaUrl, isImage,
    laravelUrl:  config.laravelUrl  || 'http://nginx:80',
    n8nSecret:   config.n8nSecret   || 'change-me-in-production',
    groqApiKey:  config.groqApiKey  || '',
    groqModel:   config.groqModel   || 'llama-3.3-70b-versatile',
    groqBaseUrl: config.groqBaseUrl || 'https://api.groq.com/openai/v1',
  }
}];

// ════════════════════════════════════════════════════════════════════
// W6 — Content & Safety Moderation
// Runs BEFORE the AI so flagged messages never reach Groq.
//
// Three checks (priority order):
//   1. Self-harm / suicidal ideation  → emergency, escalate to psychiatrie
//   2. Off-topic (non-medical)        → polite redirect
//   3. Abusive language               → polite warning
//
// Clean messages pass straight through unchanged.
// ════════════════════════════════════════════════════════════════════

const data    = $input.first().json;
const content = String(data.content || '').toLowerCase();

// ─── 1. Self-harm / suicidal ideation ──────────────────────────────
const selfHarmPatterns = [
  /suicid/i,
  /me tuer/i,
  /tuer moi/i,
  /envie de mourir/i,
  /je veux mourir/i,
  /plus envie de vivre/i,
  /fin de ma vie/i,
  /mettre fin à ma vie/i,
  /me faire du mal/i,
  /je souffre trop/i,
  /انتحار/,
  /أريد الموت/,
  /قتل نفسي/,
  /أذى نفسي/,
  /إيذاء نفسي/,
  /بغيت نموت/,
  /نقتل روحي/,
];
const isSelfHarm = selfHarmPatterns.some(p => p.test(content));

// ─── 2. Off-topic (clearly non-medical) ────────────────────────────
// Only flag when obvious off-topic keywords appear AND no medical hints,
// to avoid blocking a real medical question by accident.
const offTopicPatterns = [
  /recette de cuisine/i,
  /résultat.*foot/i,
  /match de foot/i,
  /jeux? vidéo/i,
  /cryptomonnaie/i,
  /traduction.*texte/i,
  /paroles? (de )?chanson/i,
  /météo.*demain/i,
  /score.*match/i,
];
const medicalHints = [
  /douleur/i,
  /symptôme/i,
  /malade/i,
  /fièvre/i,
  /médecin/i,
  /santé/i,
  /médicament/i,
  /traitement/i,
  /grossesse/i,
  /consultat/i,
  /صحة/,
  /مريض/,
  /ألم/,
  /دواء/,
  /طبيب/,
];
const isOffTopic =
  offTopicPatterns.some(p => p.test(content)) &&
  !medicalHints.some(p => p.test(content));

// ─── 3. Abusive language ────────────────────────────────────────────
const abusePatterns = [
  /\b(connard|salope|enculé|va te faire foutre|fils de pute)\b/i,
  /\b(مشنوق|كلب|حقير|عاهرة)\b/,
];
const isAbuse = abusePatterns.some(p => p.test(content));

// ─── Self-harm → emergency + escalate + crisis resources ───────────
if (isSelfHarm) {
  return [{
    json: {
      ...data,
      moderation: {
        flagged: true,
        reason: 'self_harm',
        callbackPayload: {
          message_id:          data.messageId,
          conversation_id:     data.conversationId,
          response:            `Je sens que vous traversez un moment très difficile. Vous n'êtes pas seul(e).

🆘 Besoin d'aide immédiate ?
📞 SOS Détresse Maroc : 0800 004 747 (gratuit, 24h/24)
📞 SAMU : 15

Je contacte un médecin pour vous maintenant.`,
          confidence:          1.0,
          escalate:            true,
          urgency_level:       'emergency',
          specialty_suggested: 'psychiatrie',
          intent:              'self_harm',
          suggest_expert:      false,
          requires_premium:    false,
          actions:             [{ type: 'call_samu', label: 'Appeler le 15 maintenant' }],
          model:               'moderation',
          tokens_used:         0,
        }
      }
    }
  }];
}

// ─── Off-topic → polite redirect ──────────────────────────────────
if (isOffTopic) {
  return [{
    json: {
      ...data,
      moderation: {
        flagged: true,
        reason: 'off_topic',
        callbackPayload: {
          message_id:          data.messageId,
          conversation_id:     data.conversationId,
          response:            `Je suis Nexora, votre assistant médical. Je suis ici uniquement pour vous aider avec vos questions de santé.

Si vous avez un symptôme, une douleur ou une question médicale, je suis à votre disposition. 😊`,
          confidence:          1.0,
          escalate:            false,
          urgency_level:       'low',
          specialty_suggested: null,
          intent:              'off_topic',
          suggest_expert:      false,
          requires_premium:    false,
          actions:             [],
          model:               'moderation',
          tokens_used:         0,
        }
      }
    }
  }];
}

// ─── Abuse → polite warning ────────────────────────────────────────
if (isAbuse) {
  return [{
    json: {
      ...data,
      moderation: {
        flagged: true,
        reason: 'abuse',
        callbackPayload: {
          message_id:          data.messageId,
          conversation_id:     data.conversationId,
          response:            `Cette plateforme est un espace médical respectueux. Merci d'utiliser un langage approprié pour que je puisse vous aider correctement.`,
          confidence:          1.0,
          escalate:            false,
          urgency_level:       'low',
          specialty_suggested: null,
          intent:              'abuse',
          suggest_expert:      false,
          requires_premium:    false,
          actions:             [],
          model:               'moderation',
          tokens_used:         0,
        }
      }
    }
  }];
}

// ─── Clean — pass through to AI ─────────────────────────────────────
return [{ json: { ...data, moderation: { flagged: false, reason: null } } }];

// Get config passed through the chain
const prevData  = $('Build AI Prompt').first().json;
const groqReply = $input.first().json;

// ─── Extract raw text from Groq ────────────────────────────────────────────
let rawContent = '';
try {
  rawContent = groqReply.choices[0].message.content;
} catch (e) {
  throw new Error('Groq response malformed: ' + JSON.stringify(groqReply));
}

// ─── Parse JSON from AI ────────────────────────────────────────────────────
let parsed = {};
try {
  const cleaned = rawContent.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    language:         'fr',
    specialty:        'medecine-generale',
    urgency_level:    'low',
    confidence:       0.8,
    escalate:         false,
    suggest_expert:   false,
    intent:           null,
    requires_premium: false,
    actions:          [],
    response:         "Je n'ai pas pu traiter votre demande. Pouvez-vous reformuler ?"
  };
}

// ─── Sanitize urgency and confidence ───────────────────────────────────────
const allowedUrgencies = ['low', 'moderate', 'urgent', 'emergency'];
let urgency = String(parsed.urgency_level || 'low').toLowerCase();
if (!allowedUrgencies.includes(urgency)) urgency = 'low';

let confidence = parseFloat(parsed.confidence ?? 0.8);
if (Number.isNaN(confidence)) confidence = 0.8;
confidence = Math.max(0, Math.min(1, confidence));

// ─── Escalation — trust the AI, only override for explicit cases ────────────
const userText = String(prevData.content || '').toLowerCase();

const patientAskedDoctor =
  /(médecin|medecin|docteur|doctor|spécialiste|specialiste|expert|rendez-vous|rdv|طبيب|دكتور)/i.test(userText);

// Force escalate only for true emergency or explicit doctor request
// For urgent/moderate — trust the AI's judgment completely
const forceEscalate = urgency === 'emergency' || patientAskedDoctor;
if (forceEscalate) parsed.escalate = true;

// suggest_expert: trust AI, just block it for emergencies
const suggestExpert = parsed.suggest_expert === true && urgency !== 'emergency';

// Validate actions array
const actions = Array.isArray(parsed.actions) ? parsed.actions : [];

// ─── Build Laravel callback payload ────────────────────────────────────────
const callbackPayload = {
  message_id:          prevData.messageId,
  conversation_id:     prevData.conversationId,
  response:            parsed.response          || '',
  confidence:          confidence,
  escalate:            parsed.escalate          ?? forceEscalate,
  urgency_level:       urgency,
  specialty_suggested: parsed.specialty         || null,
  intent:              parsed.intent            || null,
  suggest_expert:      suggestExpert,
  requires_premium:    parsed.requires_premium  ?? false,
  actions:             actions,
  model:               groqReply.model          || prevData.groqModel || 'llama-3.3-70b-versatile',
  tokens_used:         groqReply.usage?.total_tokens || 0,
};

// ─── Fetch best available doctor when AI suggests one ──────────────────────
// Adds expert_recommendation to callback so Flutter renders the doctor card.
if (suggestExpert) {
  try {
    const specialty = parsed.specialty || 'medecine-generale';
    const laravelBase = prevData.laravelUrl || 'http://nginx:80';
    const expertUrl = `${laravelBase}/api/v1/experts?specialty=${encodeURIComponent(specialty)}&available=1&per_page=1&sort=rating`;
    const expertRes = await fetch(expertUrl, {
      headers: { 'Accept': 'application/json' },
    });
    if (expertRes.ok) {
      const expertJson = await expertRes.json();
      const experts = expertJson.data || [];
      if (experts.length > 0) {
        const doc = experts[0];
        callbackPayload.expert_recommendation = {
          id:        doc.id,
          name:      doc.user?.name || 'Médecin',
          specialty: doc.category?.name || specialty,
          rating:    parseFloat(doc.rating_avg || 0),
        };
      }
    }
  } catch (_) {
    // Silent fail — expert card simply won't render, no data lost
  }
}

return [{
  json: {
    callbackPayload,
    laravelUrl:  prevData.laravelUrl  || 'http://nginx:80',
    n8nSecret:   prevData.n8nSecret   || 'change-me-in-production',
    isEmergency: urgency === 'emergency',
  }
}];

const data = $input.first().json;

const emergencyBanner = [
  '🚨 URGENCE MÉDICALE DÉTECTÉE',
  '',
  'Appelez immédiatement le 15 (SAMU Maroc) ou rendez-vous aux urgences les plus proches.',
  '',
  '─────────────────────────────',
  ''
].join('\n');

data.callbackPayload.response = emergencyBanner + data.callbackPayload.response;

return [{ json: data }];
